const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],DAY=86400000,intervals=[1,3,7,14,30],KEY='yohaku-data-v1';
const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function read(){try{const x=JSON.parse(localStorage.getItem(KEY));if(x&&Array.isArray(x.items)&&Array.isArray(x.logs))return x}catch{}return {items:[],logs:[],popup:true}}
let state=read(),view='home',editId=null,currentId=null,revealed=false,queue=[],dismissed=new Map();
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));return true}catch{toast('保存できませんでした。ブラウザの空き容量をご確認ください。');return false}}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('visible');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3300)}
function date(t,full=false){return new Intl.DateTimeFormat('ja-JP',{month:'long',day:'numeric',...(full?{hour:'2-digit',minute:'2-digit'}:{})}).format(new Date(t))}
function dayKey(t){return new Date(t).toLocaleDateString('sv-SE')}
const due=()=>state.items.filter(x=>x.next<=Date.now()).sort((a,b)=>a.next-b.next);
function icon(c){return c==='語学'?['Aa','']:c==='仕事'?['⌘','work']:c==='読書'?['▤','book']:['✧','']}
function card(x,all=false){const [symbol,cls]=icon(x.category);return `<article class="review-card"><div class="category-icon ${cls}">${symbol}</div><div class="details"><span class="tag">${escapeHTML(x.category)} · ${x.count||0}回復習</span><h3>${escapeHTML(x.title)}</h3><small>${x.next<=Date.now()?'● 復習のタイミングです':`次回 ${date(x.next,true)}`}</small></div>${all?`<div class="library-actions"><button class="review-btn" data-review="${x.id}">復習</button><button class="text-button" data-edit="${x.id}">編集</button><button class="text-button" data-delete="${x.id}">削除</button></div>`:`<button class="review-btn" data-review="${x.id}">復習する ↗</button>`}</article>`}
function render(){const ds=due(),logs=state.logs.filter(x=>dayKey(x.at)===dayKey(Date.now()));$('#today').textContent=new Intl.DateTimeFormat('ja-JP',{year:'numeric',month:'long',day:'numeric',weekday:'short'}).format(new Date());$('#navcount').textContent=state.items.length;$('#dueStat').innerHTML=ds.length+'<small>件</small>';$('#allStat').innerHTML=state.items.length+'<small>件</small>';$('#doneStat').innerHTML=logs.length+'<small>回</small>';$('#totalStat').innerHTML=state.logs.length+'<small>回</small>';$('#heroCount').textContent=ds.length+'件';$('#dueBadge').textContent=ds.length;$('#dueList').innerHTML=ds.length?ds.slice(0,4).map(x=>card(x)).join(''):`<div class="empty"><strong>${state.items.length?'今日の復習は、ひとやすみ。':'最初の学びを、植えてみましょう。'}</strong>${state.items.length?'次のタイミングになったら、お知らせします。':'覚えておきたいことを登録して、記憶を育てよう。'}<br><button class="text-button" id="emptyAdd">＋ 学びを登録する</button></div>`;
renderLibrary();renderSchedule();if(view==='settings')renderSettings();}
function renderLibrary(){const q=$('#search').value.toLowerCase(),c=$('#filter').value,items=state.items.filter(x=>(!c||x.category===c)&&(x.title+' '+x.body).toLowerCase().includes(q));$('#libraryList').innerHTML=items.length?items.map(x=>card(x,true)).join(''):'<div class="empty">学びが見つかりません。新しい学びを登録してみましょう。</div>'}
function renderSchedule(){const items=[...state.items].sort((a,b)=>a.next-b.next);let prev='';$('#schedule').innerHTML=items.length?items.map(x=>{const k=dayKey(x.next),head=k!==prev?`<h2 class="schedule-day">${x.next<=Date.now()?'復習待ち · ':''}${date(x.next)} <span class="muted">${new Date(x.next).getFullYear()}</span></h2>`:'';prev=k;return head+card(x,true)}).join(''):'<div class="empty">学びを登録すると、ここに復習予定が並びます。</div>'}
function renderSettings(){$('#settings').innerHTML=`<section class="settings-panel"><div class="eyebrow">YOUR RHYTHM</div><h2>あなたのペースで、続けよう。</h2><p>復習の目安は、前回の復習から次の間隔です。<br>「覚えていた」を選ぶと、次のステップに進みます。</p><div class="intervals">${intervals.map(x=>`<span>${x}日後</span>`).join('')}</div><p>「もう一度」は10分後、「あいまい」は1日後に再通知。30日のステップに達した後は、30日ごとに復習を続けます。忘却曲線を参考にした目安で、誰にでも共通の最適間隔ではありません。</p><hr style="border:0;border-top:1px solid var(--line);margin:25px 0"><h2>復習のお知らせ</h2><label style="display:flex;gap:10px;align-items:center"><input type="checkbox" id="popupToggle" style="width:auto" ${state.popup?'checked':''}>アプリ内の復習ポップアップを表示</label><p>アプリを開いている間、期限が来た学びを自動で表示します。閉じている間のお知らせには対応していません。再び開くと復習待ちを確認できます。</p><button class="secondary" id="notifyEnable">ブラウザ通知を${'Notification'in window&&Notification.permission==='granted'?'テストする':'有効にする'}</button><p class="muted">通知はブラウザの対応・許可が必要です。復習内容はこのブラウザに保存され、別の端末には同期されません。</p></section>`}
function setView(v){view=v;['home','library','schedule','settings'].forEach(x=>$('#'+x).hidden=x!==v);$$('.nav').forEach(x=>x.classList.toggle('active',x.dataset.view===v));const names={home:['ダッシュボード','おかえりなさい。','学んだことを、忘れない知識に。今日も少しだけ、記憶を育てましょう。'],library:['学びのライブラリ','あなたの、知識のたね。','覚えておきたい学びを、ひとつずつ集めよう。'],schedule:['復習スケジュール','次に、思い出す日。','小さな復習を重ねて、長く続く記憶へ。'],settings:['設定・通知','学びのリズムを整える。','気持ちよく続けるための、あなたの設定。']};$('#crumb').textContent=names[v][0];$('#heading').textContent=names[v][1];$('#subtitle').textContent=names[v][2];render();window.scrollTo(0,0)}
function openEditor(id=null){editId=id;const item=state.items.find(x=>x.id===id);$('#editForm').reset();$('#editTitle').textContent=item?'学びを編集':'新しい学びを登録';if(item){$('#titleInput').value=item.title;$('#bodyInput').value=item.body;$('#categoryInput').value=item.category}$('#firstInput').closest('label').hidden=!!item;$('#editor').showModal()}
$('#editForm').addEventListener('submit',e=>{e.preventDefault();const title=$('#titleInput').value.trim(),body=$('#bodyInput').value.trim();if(!title||!body){toast('タイトルと復習内容を入力してください。');return}if(editId){const x=state.items.find(x=>x.id===editId);Object.assign(x,{title,body,category:$('#categoryInput').value})}else state.items.push({id:crypto.randomUUID(),title,body,category:$('#categoryInput').value,created:Date.now(),next:Date.now()+Number($('#firstInput').value)*DAY,step:0,count:0});if(save()){$('#editor').close();render();toast(editId?'学びを更新しました':'学びを登録しました。記憶を育てていきましょう。')}});
function startReview(id){const x=state.items.find(x=>x.id===id);if(!x)return;currentId=id;revealed=false;drawReview();if(!$('#review').open)$('#review').showModal()}
function drawReview(){const x=state.items.find(x=>x.id===currentId);if(!x)return;$('#reviewContent').innerHTML=`<p class="tag">${escapeHTML(x.category)} · ${x.count}回復習</p><h2>${escapeHTML(x.title)}</h2><p class="muted">まずは、答えを見ずに思い出してみましょう。</p>${revealed?`<div class="answer">${escapeHTML(x.body)}</div><p class="muted">どのくらい思い出せましたか？</p><div class="review-grades"><button class="secondary" data-grade="again">もう一度<small>10分後</small></button><button class="secondary" data-grade="hard">あいまい<small>1日後</small></button><button class="primary" data-grade="good">覚えていた<small>${intervals[x.step]||30}日後</small></button></div>`:`<div class="review-question">少し立ち止まって、<br>頭の中の記憶をたどってみよう。</div><button class="primary" id="reveal" style="width:100%">内容を表示する</button>`}`}
function grade(g){const x=state.items.find(x=>x.id===currentId);if(!x)return;const delay=g==='again'?600000:g==='hard'?DAY:(intervals[x.step]||30)*DAY;x.next=Date.now()+delay;if(g==='good')x.step=Math.min(x.step+1,4);x.count++;state.logs.push({id:x.id,at:Date.now(),grade:g});save();dismissed.delete(x.id);render();queue=queue.filter(id=>id!==x.id);const next=queue.shift();if(next)startReview(next);else{$('#review').close();currentId=null;toast('復習を記録しました。次回：'+date(x.next,true))}}
function dismissReview(){if(currentId)dismissed.set(currentId,Date.now()+600000);queue=[];currentId=null;$('#review').close()}
function checkDue(){render();if(!state.popup||$('#editor').open||$('#review').open||document.visibilityState!=='visible')return;const items=due().filter(x=>(dismissed.get(x.id)||0)<=Date.now());if(items.length){queue=items.map(x=>x.id);startReview(queue.shift());if('Notification'in window&&Notification.permission==='granted')try{new Notification('余白 | 復習のタイミングです',{body:items.length+'件の学びを思い出しましょう。',tag:'yohaku-review'})}catch{}}}
async function notifications(){if(!('Notification'in window)){toast('このブラウザは通知に対応していません。');return}try{const p=await Notification.requestPermission();if(p==='granted'){new Notification('余白 | 通知を設定しました',{body:'アプリを開いている間、復習タイミングをお知らせします。'});toast('ブラウザ通知を有効にしました')}else toast('ブラウザ設定で通知を許可してください。')}catch{toast('通知を設定できませんでした。')}renderSettings()}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.view)setView(b.dataset.view);if(b.id==='add'||b.id==='emptyAdd')openEditor();if(b.hasAttribute('data-close'))$('#editor').close();if(b.dataset.review){queue=[];startReview(b.dataset.review)}if(b.dataset.edit)openEditor(b.dataset.edit);if(b.dataset.delete){const x=state.items.find(x=>x.id===b.dataset.delete);if(confirm('「'+x.title+'」を削除しますか？')){state.items=state.items.filter(x=>x.id!==b.dataset.delete);save();render();toast('学びを削除しました')}}if(b.id==='reveal'){revealed=true;drawReview()}if(b.dataset.grade)grade(b.dataset.grade);if(b.hasAttribute('data-review-close'))dismissReview();if(b.id==='start'){queue=due().map(x=>x.id);if(queue.length)startReview(queue.shift());else toast('今は復習待ちの学びがありません。')}if(b.id==='viewAll')setView('library');if(b.id==='bell')setView('settings');if(b.id==='notifyEnable')notifications()});
$('#search').addEventListener('input',renderLibrary);$('#filter').addEventListener('change',renderLibrary);document.addEventListener('change',e=>{if(e.target.id==='popupToggle'){state.popup=e.target.checked;save();toast(state.popup?'ポップアップを有効にしました':'ポップアップをオフにしました')}});$('#review').addEventListener('cancel',e=>{e.preventDefault();dismissReview()});document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')checkDue()});window.addEventListener('storage',e=>{if(e.key===KEY){state=read();render()}});render();setTimeout(checkDue,1800);setInterval(checkDue,30000);
